//! Small, concrete e-graphs with Python bindings generated by PyO3.
pub mod base;
mod coegraph;
pub mod macros;
pub mod prolog;
pub mod pthin;
pub mod sexp;
pub mod thin;

#[pyo3::pymodule]
mod microegg {
    #[pymodule_export]
    use crate::base::{EGraph, Node, Term};
    #[pymodule_export]
    use crate::thin::python as thin;

    // Extension submodules need this entry for `import microegg.thin`.
    #[pymodule_init]
    fn init(m: &pyo3::Bound<'_, pyo3::types::PyModule>) -> pyo3::PyResult<()> {
        use pyo3::prelude::*;
        m.py()
            .import("sys")?
            .getattr("modules")?
            .set_item("microegg.thin", m.getattr("thin")?)
    }
}
